const input = $input.first().json.body || $input.first().json;
if (!input.deal || typeof input.deal !== 'object') throw new Error('deal object is required');
const d = input.deal;
const tiers = Array.isArray(d.tiers) ? d.tiers.map(t => ({ minQty: Number(t.minQty), maxQty: t.maxQty == null ? null : Number(t.maxQty), pricePerUnit: Number(t.pricePerUnit), label: String(t.label || '') })) : [];
const issues = [];
for (let i = 0; i < tiers.length; i++) { const t = tiers[i]; if (!Number.isFinite(t.minQty) || t.minQty < 1 || !Number.isFinite(t.pricePerUnit) || t.pricePerUnit < 0) issues.push(`Tier ${i + 1} has invalid quantity or price`); if (t.maxQty != null && t.maxQty < t.minQty) issues.push(`Tier ${i + 1} maximum quantity is below minimum`); if (i && tiers[i - 1].maxQty != null && t.minQty <= tiers[i - 1].maxQty) issues.push(`Tier ${i + 1} overlaps the previous quantity range`); }
const computedSavings = Number.isFinite(Number(d.mrp)) && Number(d.mrp) > 0 && tiers.length ? Math.round((1 - tiers[tiers.length - 1].pricePerUnit / Number(d.mrp)) * 100) : null;
const evidence = { id: d.id || null, title: String(d.title || ''), category: d.category || null, description: String(d.description || ''), vendor: d.vendor || null, vendorId: d.vendorId || null, vendorVerified: d.vendorVerified ?? null, vendorRating: d.vendorRating ?? null, endDate: d.endDate || d.dealEndsAt || null, currentParticipants: Number(d.currentParticipants || 0), targetParticipants: Number(d.targetParticipants || 0), mrp: d.mrp == null ? null : Number(d.mrp), claimedSavingsPercent: d.savings == null ? null : Number(d.savings), computedSavingsPercentAtBestTier: computedSavings, tiers, pickupPoints: Array.isArray(d.pickupPoints) ? d.pickupPoints : [] };
const prompt = `Audit this proposed community group-buy deal for clarity and arithmetic consistency. Do not invent vendor credentials, product facts, market prices, legal compliance, or savings. Treat vendor verification as unknown unless supplied. Point out missing or conflicting facts for human review. This is advisory only: do not publish, cancel, or change pricing.
Deal facts: ${JSON.stringify(evidence)}
Deterministic tier checks: ${JSON.stringify(issues)}
Return JSON {"decision":"READY_FOR_REVIEW|NEEDS_CHANGES|INSUFFICIENT_INFORMATION","riskFlags":["..."],"tierAssessment":"...","savingsAssessment":"...","missingInformation":["..."],"recommendedEdits":["..."],"residentDisclosure":"..."}.`;
return [{ json: { dealId: evidence.id, evidence, deterministicIssues: issues, prompt } }];

const response = $input.first().json;
const source = $('Check Tier Data and Prepare Audit').first().json;
let audit;
try { audit = JSON.parse(response.candidates?.[0]?.content?.parts?.[0]?.text || '{}'); } catch { audit = null; }
if (!audit || !audit.decision) audit = { decision: 'INSUFFICIENT_INFORMATION', riskFlags: ['AI review unavailable; manual review required'], tierAssessment: source.deterministicIssues.length ? 'Tier data contains deterministic validation issues.' : 'Tier ranges require manual confirmation.', savingsAssessment: 'Verify savings against a documented reference price.', missingInformation: [], recommendedEdits: [], residentDisclosure: 'Confirm final price and fulfillment details with the organizer.' };
if (source.deterministicIssues.length) { audit.decision = 'NEEDS_CHANGES'; audit.riskFlags = [...new Set([...(audit.riskFlags || []), ...source.deterministicIssues])]; }
return [{ json: { status: 'success', dealId: source.dealId, auditedAt: new Date().toISOString(), evidence: source.evidence, audit } }];
